[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>AI in Clinical Decision-Making - Conference Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:wght@400;600;700&family=Inter:wght@400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2384px;
    height: 3370px;
    background: #f8f9fb;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    color: #1e293b;
    overflow: hidden;
  }

  .poster {
    width: 2384px;
    height: 3370px;
    padding: 60px 70px;
    display: flex;
    flex-direction: column;
    gap: 36px;
    background: linear-gradient(180deg, #0f172a 0%, #0f172a 320px, #f8f9fb 320px);
  }

  /* Header */
  .header {
    text-align: center;
    padding: 30px 40px 36px;
    color: #fff;
  }
  .venue {
    font-size: 22px;
    font-weight: 500;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: #5eead4;
    margin-bottom: 18px;
  }
  .poster-title {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 56px;
    font-weight: 700;
    line-height: 1.2;
    color: #fff;
    margin-bottom: 16px;
  }
  .one-liner {
    font-size: 22px;
    line-height: 1.5;
    color: #cbd5e1;
    max-width: 1600px;
    margin: 0 auto;
  }

  /* Anchor stat */
  .anchor-stat {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);
    border-radius: 20px;
    padding: 44px 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 60px;
    color: #fff;
    box-shadow: 0 4px 24px rgba(15,23,42,0.15);
  }
  .anchor-number {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 128px;
    font-weight: 700;
    color: #f59e0b;
    line-height: 1;
    text-shadow: 0 2px 12px rgba(245,158,11,0.3);
  }
  .anchor-text {
    max-width: 700px;
  }
  .anchor-text h2 {
    font-size: 32px;
    font-weight: 700;
    margin-bottom: 10px;
    color: #fbbf24;
  }
  .anchor-text p {
    font-size: 21px;
    line-height: 1.55;
    color: #e2e8f0;
  }
  .anchor-divider {
    width: 3px;
    height: 100px;
    background: rgba(94,234,212,0.4);
    border-radius: 2px;
  }
  .anchor-right {
    display: flex;
    flex-direction: column;
    gap: 6px;
    align-items: center;
  }
  .anchor-right .sub-num {
    font-size: 52px;
    font-weight: 700;
    color: #5eead4;
    font-family: 'Source Serif 4', Georgia, serif;
  }
  .anchor-right .sub-label {
    font-size: 17px;
    color: #94a3b8;
    text-align: center;
    max-width: 200px;
  }

  /* Content grid */
  .content-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 36px;
    flex: 1;
  }

  .section {
    background: #fff;
    border-radius: 16px;
    padding: 36px 40px;
    box-shadow: 0 2px 12px rgba(15,23,42,0.06);
    border-top: 4px solid #0f172a;
    display: flex;
    flex-direction: column;
  }
  .section.teal-border { border-top-color: #0d9488; }
  .section.amber-border { border-top-color: #d97706; }
  .section.red-border { border-top-color: #dc2626; }
  .section.navy-border { border-top-color: #1e3a5f; }
  .section.full-width {
    grid-column: 1 / -1;
  }

  .section-tag {
    font-size: 13px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: #64748b;
    margin-bottom: 8px;
  }
  .section h3 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 30px;
    font-weight: 700;
    color: #0f172a;
    margin-bottom: 16px;
  }
  .section p {
    font-size: 19px;
    line-height: 1.6;
    color: #475569;
  }

  /* Comparison bars */
  .comparison {
    display: flex;
    flex-direction: column;
    gap: 20px;
    margin-top: 20px;
    flex: 1;
  }
  .comp-row {
    display: flex;
    align-items: center;
    gap: 16px;
  }
  .comp-label {
    width: 130px;
    font-size: 16px;
    font-weight: 600;
    color: #334155;
    text-align: right;
  }
  .comp-bar-wrap {
    flex: 1;
    height: 36px;
    background: #f1f5f9;
    border-radius: 8px;
    position: relative;
    overflow: hidden;
  }
  .comp-bar {
    height: 100%;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 14px;
    font-size: 16px;
    font-weight: 700;
    color: #fff;
  }
  .comp-bar.ai { background: linear-gradient(90deg, #0d9488, #14b8a6); }
  .comp-bar.clinician { background: linear-gradient(90deg, #64748b, #94a3b8); }

  /* Metric cards */
  .metric-cards {
    display: flex;
    gap: 24px;
    margin-top: 16px;
  }
  .metric-card {
    flex: 1;
    background: #f8fafc;
    border-radius: 12px;
    padding: 24px;
    text-align: center;
    border: 1px solid #e2e8f0;
  }
  .metric-card .mc-value {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 48px;
    font-weight: 700;
    color: #0f172a;
  }
  .metric-card .mc-value.teal { color: #0d9488; }
  .metric-card .mc-value.amber { color: #d97706; }
  .metric-card .mc-label {
    font-size: 15px;
    color: #64748b;
    margin-top: 6px;
    line-height: 1.4;
  }

  /* Domain table */
  .domain-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 16px;
    font-size: 17px;
  }
  .domain-table th {
    background: #f1f5f9;
    padding: 12px 16px;
    text-align: left;
    font-weight: 600;
    color: #334155;
    border-bottom: 2px solid #e2e8f0;
  }
  .domain-table td {
    padding: 11px 16px;
    border-bottom: 1px solid #f1f5f9;
    color: #475569;
  }
  .domain-table tr:hover td { background: #f8fafc; }
  .highlight-cell {
    font-weight: 700;
    color: #0d9488 !important;
  }

  /* Warning box */
  .warning-box {
    background: linear-gradient(135deg, #fef3c7, #fff7ed);
    border-left: 5px solid #d97706;
    border-radius: 10px;
    padding: 24px 28px;
    margin-top: 16px;
    display: flex;
    align-items: center;
    gap: 24px;
  }
  .warning-icon {
    font-size: 52px;
    color: #d97706;
    flex-shrink: 0;
  }
  .warning-number {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 64px;
    font-weight: 700;
    color: #dc2626;
    line-height: 1;
    flex-shrink: 0;
  }
  .warning-content {
    flex: 1;
  }
  .warning-content strong {
    font-size: 20px;
    color: #92400e;
  }
  .warning-content p {
    font-size: 17px;
    color: #78350f;
    margin-top: 4px;
  }

  /* Barriers list */
  .barriers {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-top: 16px;
  }
  .barrier-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    background: #f8fafc;
    border-radius: 10px;
    padding: 16px 18px;
    border: 1px solid #e2e8f0;
  }
  .barrier-icon {
    width: 36px;
    height: 36px;
    background: #0f172a;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #5eead4;
    font-size: 18px;
    font-weight: 700;
    flex-shrink: 0;
  }
  .barrier-item strong {
    display: block;
    font-size: 17px;
    color: #0f172a;
    margin-bottom: 3px;
  }
  .barrier-item span {
    font-size: 15px;
    color: #64748b;
    line-height: 1.4;
  }

  /* Recommendations */
  .rec-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
    margin-top: 12px;
  }
  .rec-item {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 14px 18px;
    background: #f0fdfa;
    border-radius: 10px;
    border: 1px solid #ccfbf1;
  }
  .rec-num {
    width: 34px;
    height: 34px;
    background: #0d9488;
    color: #fff;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 17px;
    font-weight: 700;
    flex-shrink: 0;
  }
  .rec-item p {
    font-size: 18px;
    color: #334155;
    line-height: 1.5;
  }
  .rec-item strong { color: #0f172a; }

  /* Footer */
  .footer {
    text-align: center;
    padding: 16px 0 0;
    font-size: 16px;
    color: #94a3b8;
    border-top: 2px solid #e2e8f0;
  }
  .footer strong { color: #64748b; }

  /* Sensitivity highlight boxes */
  .sens-compare {
    display: flex;
    gap: 28px;
    margin: 18px 0;
    justify-content: center;
  }
  .sens-box {
    text-align: center;
    padding: 20px 36px;
    border-radius: 14px;
    min-width: 200px;
  }
  .sens-box.ai-box {
    background: linear-gradient(135deg, #0d9488, #14b8a6);
    color: #fff;
  }
  .sens-box.clin-box {
    background: #f1f5f9;
    color: #334155;
  }
  .sens-box .sens-val {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 56px;
    font-weight: 700;
    line-height: 1;
  }
  .sens-box .sens-lbl {
    font-size: 17px;
    margin-top: 6px;
    opacity: 0.85;
  }
  .sens-box.ai-box .sens-val { color: #fff; }
  .sens-box.clin-box .sens-val { color: #475569; }
  .sens-vs {
    display: flex;
    align-items: center;
    font-size: 28px;
    font-weight: 700;
    color: #94a3b8;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="venue">The Lancet Digital Health &mdash; AI in Clinical Medicine Symposium</div>
    <div class="poster-title">Artificial Intelligence in Clinical Decision-Making:<br>Performance, Safety, and Implementation Gaps</div>
    <div class="one-liner">A synthesis of current evidence on AI-assisted clinical decision support systems, highlighting diagnostic accuracy gains, safety considerations, and the translational gap from research to bedside deployment.</div>
  </div>

  <!-- ANCHOR STAT -->
  <div class="anchor-stat">
    <div style="text-align:center;">
      <div class="anchor-number">&lt;5%</div>
      <div style="font-size:20px;color:#fbbf24;font-weight:600;margin-top:6px;">PROSPECTIVE VALIDATION RATE</div>
    </div>
    <div class="anchor-divider"></div>
    <div class="anchor-text">
      <h2>The Implementation Gap</h2>
      <p>Of all AI models published in peer-reviewed literature, fewer than 5% have undergone prospective clinical validation in real-world settings &mdash; despite 692 FDA-cleared AI/ML medical devices as of 2023.</p>
    </div>
    <div class="anchor-divider"></div>
    <div class="anchor-right">
      <div class="sub-num">692</div>
      <div class="sub-label">FDA-cleared AI/ML medical devices (2023)</div>
    </div>
  </div>

  <!-- MAIN CONTENT GRID -->
  <div class="content-grid">

    <!-- Section 1: Diagnostic Performance -->
    <div class="section teal-border">
      <div class="section-tag">Findings</div>
      <h3>Diagnostic Performance</h3>
      <p>Across 400+ studies, AI-assisted diagnosis demonstrated substantially higher sensitivity compared to clinician-only workflows, with the largest gains in medical imaging.</p>

      <div class="sens-compare">
        <div class="sens-box ai-box">
          <div class="sens-val">87.5%</div>
          <div class="sens-lbl">AI Sensitivity</div>
        </div>
        <div class="sens-vs">vs</div>
        <div class="sens-box clin-box">
          <div class="sens-val">78.2%</div>
          <div class="sens-lbl">Clinician Sensitivity</div>
        </div>
      </div>

      <div class="metric-cards">
        <div class="metric-card">
          <div class="mc-value teal">93.1%</div>
          <div class="mc-label">AI Specificity</div>
        </div>
        <div class="metric-card">
          <div class="mc-value">91.4%</div>
          <div class="mc-label">Clinician Specificity</div>
        </div>
        <div class="metric-card">
          <div class="mc-value amber">32%</div>
          <div class="mc-label">Faster Turnaround</div>
        </div>
      </div>
    </div>

    <!-- Section 2: Domain Performance Table -->
    <div class="section navy-border">
      <div class="section-tag">By Domain</div>
      <h3>Performance Across Specialties</h3>
      <p>Deep learning architectures consistently outperformed individual readers, with the greatest gains in radiology and pathology.</p>
      <table class="domain-table">
        <thead>
          <tr>
            <th>Domain</th>
            <th>AI Sensitivity</th>
            <th>Clinician Sensitivity</th>
            <th>AI Specificity</th>
            <th>Clinician Specificity</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td><strong>Radiology</strong></td>
            <td class="highlight-cell">89.3%</td>
            <td>79.8%</td>
            <td>94.0%</td>
            <td>92.1%</td>
          </tr>
          <tr>
            <td><strong>Dermatology</strong></td>
            <td class="highlight-cell">86.7%</td>
            <td>76.5%</td>
            <td>91.8%</td>
            <td>89.4%</td>
          </tr>
          <tr>
            <td><strong>Ophthalmology</strong></td>
            <td class="highlight-cell">90.1%</td>
            <td>82.3%</td>
            <td>95.2%</td>
            <td>93.7%</td>
          </tr>
          <tr>
            <td><strong>Pathology</strong></td>
            <td class="highlight-cell">84.0%</td>
            <td>74.1%</td>
            <td>91.5%</td>
            <td>90.0%</td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Section 3: Safety & Bias -->
    <div class="section red-border">
      <div class="section-tag">Safety & Equity</div>
      <h3>Bias Assessment: An Alarming Gap</h3>
      <p>Safety and equity remain critically underexamined. Performance disparities of 5&ndash;12 percentage points affect underrepresented populations.</p>

      <div class="warning-box">
        <div class="warning-number">18%</div>
        <div class="warning-content">
          <strong>Only 18% of studies reported any formal bias assessment</strong>
          <p>Demographic-stratified performance reporting across age, sex, ethnicity, and socioeconomic status remains alarmingly rare. Dermatology AI trained predominantly on lighter skin tones showed the most significant disparities.</p>
        </div>
      </div>

      <div class="metric-cards" style="margin-top:18px;">
        <div class="metric-card">
          <div class="mc-value" style="color:#dc2626;">&lt;1%</div>
          <div class="mc-label">Adverse events in prospective trials</div>
        </div>
        <div class="metric-card">
          <div class="mc-value" style="color:#d97706;">5&ndash;12pp</div>
          <div class="mc-label">Sensitivity gap for underrepresented groups</div>
        </div>
      </div>
      <p style="margin-top:14px;font-size:16px;color:#94a3b8;">Under-reporting of safety events is suspected. Standardised safety-reporting frameworks for AI-CDSS remain absent.</p>
    </div>

    <!-- Section 4: Barriers -->
    <div class="section amber-border">
      <div class="section-tag">Barriers</div>
      <h3>Why AI Stalls at the Bedside</h3>
      <p>Key barriers preventing AI models from reaching routine clinical use:</p>
      <div class="barriers">
        <div class="barrier-item">
          <div class="barrier-icon">1</div>
          <div>
            <strong>Data Infrastructure</strong>
            <span>Fragmented EHR systems and lack of interoperability standards</span>
          </div>
        </div>
        <div class="barrier-item">
          <div class="barrier-icon">2</div>
          <div>
            <strong>Regulatory Uncertainty</strong>
            <span>Evolving frameworks lagging behind AI development pace</span>
          </div>
        </div>
        <div class="barrier-item">
          <div class="barrier-icon">3</div>
          <div>
            <strong>Clinician Trust</strong>
            <span>Insufficient explainability and transparency of model outputs</span>
          </div>
        </div>
        <div class="barrier-item">
          <div class="barrier-icon">4</div>
          <div>
            <strong>Economic Evidence</strong>
            <span>Limited cost-effectiveness analyses for health-system investment</span>
          </div>
        </div>
        <div class="barrier-item" style="grid-column: 1 / -1; max-width: 50%; margin: 0 auto;">
          <div class="barrier-icon">5</div>
          <div>
            <strong>Workflow Integration</strong>
            <span>Poor alignment of AI tools with existing clinical workflows</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Section 5: Recommendations (full width) -->
    <div class="section teal-border full-width">
      <div class="section-tag">Path Forward</div>
      <h3>Recommendations &amp; Future Directions</h3>
      <div class="rec-list" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">
        <div class="rec-item">
          <div class="rec-num">1</div>
          <p><strong>Mandate prospective validation</strong> before clinical deployment, including multi-site and diverse-population trials.</p>
