[metadata] {"type": "update", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>AI in Clinical Decision-Making - Conference Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;0,8..60,700;1,8..60,400&family=Inter:wght@400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2384px;
    height: 3370px;
    background: #f8f9fb;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    color: #1e293b;
    overflow: hidden;
  }

  .poster {
    width: 2384px;
    height: 3370px;
    padding: 56px 64px;
    display: flex;
    flex-direction: column;
    gap: 30px;
    background: linear-gradient(180deg, #0f172a 0%, #0f172a 340px, #f8f9fb 340px);
  }

  /* Header */
  .header {
    text-align: center;
    padding: 24px 40px 32px;
    color: #fff;
  }
  .venue {
    font-size: 21px;
    font-weight: 500;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #5eead4;
    margin-bottom: 16px;
  }
  .poster-title {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 58px;
    font-weight: 700;
    line-height: 1.18;
    color: #fff;
    margin-bottom: 14px;
  }
  .one-liner {
    font-size: 21px;
    line-height: 1.5;
    color: #cbd5e1;
    max-width: 1700px;
    margin: 0 auto;
  }

  /* Anchor stat banner */
  .anchor-stat {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 100%);
    border-radius: 18px;
    padding: 38px 56px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 48px;
    color: #fff;
    box-shadow: 0 4px 24px rgba(15,23,42,0.18);
  }
  .anchor-number {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 120px;
    font-weight: 700;
    color: #f59e0b;
    line-height: 1;
    text-shadow: 0 2px 12px rgba(245,158,11,0.3);
  }
  .anchor-sub-label {
    font-size: 19px;
    color: #fbbf24;
    font-weight: 600;
    margin-top: 4px;
    letter-spacing: 1px;
    text-align: center;
  }
  .anchor-divider {
    width: 2px;
    height: 90px;
    background: rgba(94,234,212,0.35);
    border-radius: 2px;
  }
  .anchor-text h2 {
    font-size: 30px;
    font-weight: 700;
    margin-bottom: 8px;
    color: #fbbf24;
  }
  .anchor-text p {
    font-size: 20px;
    line-height: 1.55;
    color: #e2e8f0;
    max-width: 660px;
  }
  .anchor-right {
    text-align: center;
  }
  .anchor-right .sub-num {
    font-size: 50px;
    font-weight: 700;
    color: #5eead4;
    font-family: 'Source Serif 4', Georgia, serif;
    line-height: 1;
  }
  .anchor-right .sub-label {
    font-size: 16px;
    color: #94a3b8;
    margin-top: 6px;
    max-width: 180px;
  }

  /* Content area */
  .content-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 28px;
    flex: 1;
  }

  .section {
    background: #fff;
    border-radius: 14px;
    padding: 32px 36px;
    box-shadow: 0 2px 12px rgba(15,23,42,0.06);
    border-top: 4px solid #0f172a;
  }
  .section.teal-border { border-top-color: #0d9488; }
  .section.amber-border { border-top-color: #d97706; }
  .section.red-border { border-top-color: #dc2626; }
  .section.navy-border { border-top-color: #1e3a5f; }
  .section.full-width { grid-column: 1 / -1; }

  .section-tag {
    font-size: 13px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: #64748b;
    margin-bottom: 6px;
  }
  .section h3 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 28px;
    font-weight: 700;
    color: #0f172a;
    margin-bottom: 12px;
  }
  .section p {
    font-size: 18px;
    line-height: 1.6;
    color: #475569;
  }

  /* Background section */
  .bg-section {
    background: #fff;
    border-radius: 14px;
    padding: 30px 36px;
    box-shadow: 0 2px 12px rgba(15,23,42,0.06);
    border-left: 5px solid #0f172a;
    display: flex;
    gap: 40px;
    align-items: center;
  }
  .bg-section .bg-text {
    flex: 1;
  }
  .bg-section h3 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 26px;
    font-weight: 700;
    color: #0f172a;
    margin-bottom: 8px;
  }
  .bg-section p {
    font-size: 18px;
    line-height: 1.6;
    color: #475569;
  }
  .bg-section .bg-highlight {
    font-size: 17px;
    color: #0d9488;
    font-weight: 600;
    margin-top: 8px;
  }
  .bg-stats {
    display: flex;
    gap: 24px;
    flex-shrink: 0;
  }
  .bg-stat-card {
    background: #f0fdfa;
    border: 1px solid #ccfbf1;
    border-radius: 12px;
    padding: 18px 24px;
    text-align: center;
    min-width: 140px;
  }
  .bg-stat-card .bsv {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 36px;
    font-weight: 700;
    color: #0d9488;
    line-height: 1;
  }
  .bg-stat-card .bsl {
    font-size: 14px;
    color: #64748b;
    margin-top: 4px;
  }

  /* Sensitivity comparison */
  .sens-compare {
    display: flex;
    gap: 24px;
    margin: 16px 0;
    justify-content: center;
    align-items: center;
  }
  .sens-box {
    text-align: center;
    padding: 18px 32px;
    border-radius: 14px;
    min-width: 190px;
  }
  .sens-box.ai-box {
    background: linear-gradient(135deg, #0d9488, #14b8a6);
    color: #fff;
  }
  .sens-box.clin-box {
    background: #f1f5f9;
    color: #334155;
  }
  .sens-box .sens-val {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 52px;
    font-weight: 700;
    line-height: 1;
  }
  .sens-box .sens-lbl {
    font-size: 16px;
    margin-top: 4px;
    opacity: 0.85;
  }
  .sens-vs {
    font-size: 26px;
    font-weight: 700;
    color: #94a3b8;
  }

  /* Metric cards */
  .metric-cards {
    display: flex;
    gap: 18px;
    margin-top: 14px;
  }
  .metric-card {
    flex: 1;
    background: #f8fafc;
    border-radius: 12px;
    padding: 18px;
    text-align: center;
    border: 1px solid #e2e8f0;
  }
  .metric-card .mc-value {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 40px;
    font-weight: 700;
    color: #0f172a;
  }
  .metric-card .mc-value.teal { color: #0d9488; }
  .metric-card .mc-value.amber { color: #d97706; }
  .metric-card .mc-label {
    font-size: 14px;
    color: #64748b;
    margin-top: 4px;
  }

  /* Domain table */
  .domain-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 14px;
    font-size: 16px;
  }
  .domain-table th {
